"""Hindi names, short codes, categories, Hindi descriptions and inspection
checklists for Uttarakhand GIs.  Keyed by normalised GI name (see norm()).
Matching is loose: lookup('Uttarakhand Aipan') and lookup('Aipan') hit the same entry.
"""
import re


def norm(s):
    """Lowercase, alphanumerics only."""
    return re.sub(r'[^a-z0-9]', '', (s or '').lower())


def _c(en, hi):
    return {"en": en, "hi": hi}


