def lookup(name):
    """Loose match: the longest alias that is contained in (or contains) the normalised name."""
    n = norm(name)
    best, best_len = None, 0
    for key, entry in ENRICHMENT.items():
        if len(key) >= 4 and (key in n or n in key) and len(key) > best_len:
            best, best_len = entry, len(key)
    return best
